    return (repr(v))
_emit("nothing.NoneType.null", _p0)
L2_SRC_EOF
if timeout 60 python3 main.py > run.out 2> run.err; then :; else
  echo "nothing.NoneType: run ended early ($(grep -c "|" run.out) lines printed)"
